<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {useAuth} from '../../entities/auth/model'
import {request,errorMessage,isCancelled} from '../../shared/api/client'
import type {Connection} from '../../shared/interfaces'
import {text,datetime} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
import Empty from '../../shared/ui/Empty.vue'
import Notice from '../../shared/ui/Notice.vue'
const auth=useAuth(),connections=ref<Connection[]>([]),links=ref<Record<string,unknown>[]>([]),deliveries=ref<Record<string,unknown>[]>([]),error=ref(''),loading=ref(true)
let timer:ReturnType<typeof setInterval>|undefined
const integrations=[{kind:'telphin',name:'Телфин',logo:'Т',description:'История вызовов, записи разговоров и события вашей АТС.'},{kind:'amocrm',name:'amoCRM',logo:'a',description:'Привязка контактов и сделок, отправка резюме и оценки разговора.'},{kind:'sheets',name:'Google Таблицы',logo:'▤',description:'Обновление результатов звонков в таблице без повторных строк.'},{kind:'asr',name:'Расшифровка записей',logo:'≋',description:'Преобразование аудио в текст перед оценкой диалога.'},{kind:'analysis',name:'Нейросетевой анализ',logo:'✦',description:'Оценка качества, резюме, договорённости и автоматическая разметка.'}]
function connection(kind:string){return connections.value.find(c=>c.kind===kind)}
function isDemo(kind:string){return connection(kind)?.config.provider==='demo'}
function stateLabel(state:unknown){return({delivered:'Доставлено',completed:'Завершено',pending:'В очереди',running:'Обрабатывается',failed:'Ошибка',error:'Ошибка',uncertain:'Нужна проверка',revoked:'Доступ отозван',configured:'Подключено',disconnected:'Отключено'} as Record<string,string>)[String(state)]||text(state)}
async function load(background=false){if(!background)loading.value=true;try{const[c,i]=await Promise.all([request<{items:Connection[]}>('/connections'),request<{links:Record<string,unknown>[];deliveries:Record<string,unknown>[]}>('/integrations')]);connections.value=c.items;links.value=i.links;deliveries.value=i.deliveries;error.value=''}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{loading.value=false}}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load(true)},15000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><span class="eyebrow">Свяжите звонки с бизнес-процессами</span><h1>Интеграции</h1><p>Ваши источники данных и каналы доставки результатов.</p></div><button class="button" @click="load()"><Icon name="refresh" :size="15"/>Обновить</button></div><Notice :message="error" kind="error"/><Empty v-if="loading" loading/><template v-else><div class="connection-grid" style="margin-bottom:24px"><div v-for="item in integrations" :key="item.kind" class="card connection-card"><div class="section-title" style="margin:0"><span class="connection-logo" :style="item.kind==='amocrm'?{background:'#edf5fd',color:'#78a8ce'}:item.kind==='analysis'?{background:'#f0edfa',color:'#a18bc0'}:{}">{{item.logo}}</span><span class="badge" :class="isDemo(item.kind)?'amber':connection(item.kind)?.state==='configured'?'teal':connection(item.kind)?.state==='error'?'red':'outline'">{{isDemo(item.kind)?'Только демо':connection(item.kind)?stateLabel(connection(item.kind)!.state):'Не подключено'}}</span></div><h3>{{item.name}}</h3><p>{{item.description}}</p><div class="row-actions"><span v-if="connection(item.kind)?.last_sync_at" class="subtle">{{datetime(connection(item.kind)?.last_sync_at)}}</span><span v-else class="subtle">Отдельное подключение компании</span><RouterLink class="text-link" :to="'/settings/'+item.kind">{{auth.isOwner?'Настроить':'Посмотреть'}} →</RouterLink></div></div></div>
<div class="notice info" style="margin-bottom:22px">Работа со сделками: привяжи звонок к нужной сделке amoCRM и отправь резюме из карточки. Для Google Таблиц выбери документ, лист и соответствие колонок в настройках; результаты можно распределять дальше формулами или Apps Script.</div><div class="card" style="margin-bottom:22px"><div class="card-header"><div><h3>Журнал доставки</h3><p>Поставленные в очередь и отправленные результаты анализа</p></div><span class="badge outline">{{deliveries.length}} записей</span></div><div v-if="deliveries.length" class="table-wrap"><table class="data-table"><thead><tr><th>Назначение</th><th>Звонок</th><th>Состояние</th><th>Обновлено</th><th>Результат</th></tr></thead><tbody><tr v-for="(item,i) in deliveries" :key="String(item.id||i)"><td class="primary-text">{{text(item.provider||item.kind)}}</td><td><RouterLink v-if="item.call_id" class="text-link" :to="'/calls/'+item.call_id">Открыть звонок →</RouterLink><span v-else>—</span></td><td><span class="job-state" :class="String(item.state)">{{stateLabel(item.state)}}</span></td><td>{{datetime(item.updated_at||item.created_at)}}</td><td>{{text(item.last_error||item.error||item.external_id||item.message)}}</td></tr></tbody></table></div><Empty v-else title="Результаты ещё не отправлялись" description="Выберите звонки в журнале или отправьте результат из карточки разговора."/></div>
<div class="card"><div class="card-header"><div><h3>Связанные сделки</h3><p>Явно выбранные связи звонков с контактами и сделками</p></div></div><div v-if="links.length" class="table-wrap"><table class="data-table"><thead><tr><th>Сервис</th><th>Контакт</th><th>Сделка</th><th>Звонок</th></tr></thead><tbody><tr v-for="(link,i) in links" :key="String(link.id||i)"><td>{{text(link.provider)}}</td><td>{{text(link.contact_id)}}</td><td>{{text(link.deal_id)}}</td><td><RouterLink v-if="link.call_id" class="text-link" :to="'/calls/'+link.call_id">Открыть →</RouterLink></td></tr></tbody></table></div><Empty v-else title="Связей пока нет" description="В карточке звонка можно найти контакт и выбрать нужную сделку amoCRM."/></div><p class="token-hint">При неопределённом результате внешнего запроса система сохраняет состояние «Нужна проверка», чтобы не создавать дубли вслепую. Ошибка интеграции не блокирует журнал звонков.</p></template></template>
